def process(zhvi) -> pd.DataFrame:
    import pandas as pd
    import re

    cols = list(zhvi.columns)

    # Identify likely id/geography columns
    id_like = [c for c in cols if re.search(r'(state|region|name|county|metro|city|zip|fips)', str(c), re.I)]

    # Identify time-series columns
    time_cols = []
    for c in cols:
        s = str(c)
        if re.fullmatch(r'\d{4}', s) or re.fullmatch(r'\d{4}-\d{2}', s) or re.fullmatch(r'\d{4}-\d{2}-\d{2}', s):
            time_cols.append(c)

    # Locate 2005 and 2010 columns if present
    col2005 = None
    col2010 = None
    for c in time_cols:
        if str(c).startswith('2005') and col2005 is None:
            col2005 = c
        if str(c).startswith('2010') and col2010 is None:
            col2010 = c

    out = {
        'n_rows': [len(zhvi)],
        'n_cols': [len(cols)],
        'first_25_cols': [', '.join([str(c) for c in cols[:25]])],
        'id_like_cols': [', '.join([str(c) for c in id_like[:25]])],
        'n_time_cols': [len(time_cols)],
        'first_10_time_cols': [', '.join([str(c) for c in time_cols[:10]])],
        'has_2005_col': [col2005 is not None],
        'col2005': [str(col2005) if col2005 is not None else None],
        'has_2010_col': [col2010 is not None],
        'col2010': [str(col2010) if col2010 is not None else None],
    }

    # Add first-row snapshot for a few key columns
    snap_cols = []
    for c in id_like[:3]:
        snap_cols.append(c)
    for c in [col2005, col2010]:
        if c is not None:
            snap_cols.append(c)
    snap_cols = [c for c in snap_cols if c in zhvi.columns]

    snap = {}
    if len(zhvi) > 0 and len(snap_cols) > 0:
        row0 = zhvi.iloc[0]
        for c in snap_cols:
            snap[f'row0_{c}'] = [row0[c]]

    return pd.concat([pd.DataFrame(out), pd.DataFrame(snap)], axis=1)

def process(zhvi) -> pd.DataFrame:
    import pandas as pd
    import re

    cols = list(zhvi.columns)

    id_like = []
    id_pat = re.compile(r"(state|region|name|county|metro|city|zip|fips|id|abbr|code)", re.I)
    for c in cols:
        if id_pat.search(str(c)):
            id_like.append(c)

    time_cols = []
    time_pat = re.compile(r"^(\d{4})([-_/](\d{1,2})([-_/](\d{1,2}))?)?$")
    for c in cols:
        if time_pat.match(str(c).strip()):
            time_cols.append(c)

    def find_year_cols(year: str):
        ys = []
        for c in time_cols:
            if str(c).strip().startswith(year):
                ys.append(c)
        return ys

    y2005 = find_year_cols('2005')
    y2010 = find_year_cols('2010')

    sample = zhvi.head(1)
    sample_dict = {}
    for c in (id_like[:3] + y2005[:1] + y2010[-1:]):
        if c in sample.columns:
            sample_dict[str(c)] = sample.iloc[0][c]

    out = {
        'nrows': [len(zhvi)],
        'ncols': [len(cols)],
        'first25_cols': [', '.join(map(str, cols[:25]))],
        'id_like_cols': [', '.join(map(str, id_like[:25]))],
        'time_cols_count': [len(time_cols)],
        'time_cols_first5': [', '.join(map(str, time_cols[:5]))],
        'time_cols_last5': [', '.join(map(str, time_cols[-5:]))],
        'cols_starting_2005': [', '.join(map(str, y2005[:10]))],
        'cols_starting_2010': [', '.join(map(str, y2010[:10]))],
        'sample_values': [str(sample_dict)]
    }
    return pd.DataFrame(out)

def process(zhvi, stateMap) -> pd.DataFrame:
    import pandas as pd
    import numpy as np
    import re

    df = zhvi.copy()

    # --- identify state column ---
    preferred = [
        'state', 'State', 'state_abbr', 'StateName', 'state_name',
        'RegionName', 'regionname', 'Region', 'region'
    ]
    state_col = None
    for c in preferred:
        if c in df.columns:
            state_col = c
            break
    if state_col is None:
        # regex fallback
        for c in df.columns:
            if re.search(r'(?i)\bstate\b', str(c)) or re.search(r'(?i)state', str(c)):
                state_col = c
                break

    if state_col is None:
        # Cannot proceed; return diagnostic
        return pd.DataFrame([{
            'error': 'Could not identify a state column in ZHVI table',
            'columns': ','.join(map(str, df.columns[:50]))
        }])

    # --- detect time series columns ---
    def parse_date_like(col):
        s = str(col)
        # accept YYYY, YYYY-MM, YYYY-MM-DD
        if re.fullmatch(r'\d{4}', s):
            return pd.Timestamp(f'{s}-01-01')
        if re.fullmatch(r'\d{4}-\d{2}', s):
            return pd.Timestamp(f'{s}-01')
        if re.fullmatch(r'\d{4}-\d{2}-\d{2}', s):
            return pd.Timestamp(s)
        return None

    date_cols = []
    for c in df.columns:
        ts = parse_date_like(c)
        if ts is not None:
            date_cols.append((c, ts))

    if not date_cols:
        return pd.DataFrame([{
            'error': 'Could not detect any time-series columns (YYYY / YYYY-MM / YYYY-MM-DD) in ZHVI table',
            'state_col': state_col,
            'n_cols': len(df.columns)
        }])

    date_df = pd.DataFrame(date_cols, columns=['col', 'ts'])

    # endpoints inclusive between 2005 and 2010
    start2005 = pd.Timestamp('2005-01-01')
    end2005 = pd.Timestamp('2005-12-31')
    start2010 = pd.Timestamp('2010-01-01')
    end2010 = pd.Timestamp('2010-12-31')

    cols_2005 = date_df[(date_df['ts'] >= start2005) & (date_df['ts'] <= end2005)].sort_values('ts')
    cols_2010 = date_df[(date_df['ts'] >= start2010) & (date_df['ts'] <= end2010)].sort_values('ts')

    if cols_2005.empty or cols_2010.empty:
        return pd.DataFrame([{
            'error': 'Missing required year columns',
            'state_col': state_col,
            'min_ts': date_df['ts'].min(),
            'max_ts': date_df['ts'].max(),
            'n_2005_cols': int(cols_2005.shape[0]),
            'n_2010_cols': int(cols_2010.shape[0])
        }])

    # Use the earliest available observation in 2005 and the latest in 2010
    col_2005 = cols_2005.iloc[0]['col']
    col_2010 = cols_2010.iloc[-1]['col']

    # --- compute loss without dropping rows unnecessarily ---
    v2005 = pd.to_numeric(df[col_2005], errors='coerce')
    v2010 = pd.to_numeric(df[col_2010], errors='coerce')
    loss = v2005 - v2010

    out = pd.DataFrame({
        'state_raw': df[state_col].astype(str),
        'value_2005_col': col_2005,
        'value_2010_col': col_2010,
        'loss': loss
    })

    # If state column is actually RegionName, it may contain full state names already.
    # We'll try to map abbreviations first when state_raw is 2-letter.
    out['state_abbr'] = out['state_raw'].where(out['state_raw'].str.fullmatch(r'[A-Z]{2}'))

    # Aggregate total loss by state_raw (or abbr when available)
    # Use min_count=1 to avoid turning all-NaN groups into 0.
    grouped = (
        out.assign(state_key=np.where(out['state_abbr'].notna(), out['state_abbr'], out['state_raw']))
           .groupby('state_key', dropna=False)['loss']
           .sum(min_count=1)
           .reset_index(name='total_loss')
    )

    # Keep only positive loss (value decrease)
    grouped = grouped[grouped['total_loss'] > 0].copy()

    # Map abbreviations to full names where possible
    sm = stateMap.copy()
    sm['state_abbr'] = sm['state_abbr'].astype(str)
    grouped = grouped.merge(sm, left_on='state_key', right_on='state_abbr', how='left')
    grouped['state_full_final'] = grouped['state_full'].fillna(grouped['state_key'])

    top3 = grouped.sort_values('total_loss', ascending=False).head(3)

    return top3[['state_full_final', 'total_loss', 'value_2005_col', 'value_2010_col']].rename(
        columns={'state_full_final': 'state_full'}
    )

